arguments.command:
curl -s -m 30 https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: <TOKEN>' --data '{"query":"{ teams { nodes { id name key memberships(first: 100) { nodes { user { id name email } owner } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for t in d['data']['teams']['nodes']:
    for m in t['memberships']['nodes']:
        if m.get('owner'):
            print(t['key'], t['name'], '->', m['user']['name'], m['user']['email'], m['user']['id'])
"

